#[cfg(test)]
mod grid_allocation_probe {
    use std::alloc::{GlobalAlloc, Layout, System};
    use std::cell::Cell;
    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(false) };
        static LIVE: Cell<isize> = const { Cell::new(0) };
        static PEAK: Cell<isize> = const { Cell::new(0) };
    }
    fn account(delta: isize) {
        let _ = ENABLED.try_with(|enabled| {
            if enabled.get() {
                LIVE.with(|live| {
                    let next=live.get()+delta;
                    live.set(next);
                    PEAK.with(|peak| peak.set(peak.get().max(next)));
                });
            }
        });
    }
    struct Probe;
    unsafe impl GlobalAlloc for Probe {
        unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
            let p=unsafe { System.alloc(layout) };
            if !p.is_null() { account(layout.size() as isize); } p
        }
        unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
            let p=unsafe { System.alloc_zeroed(layout) };
            if !p.is_null() { account(layout.size() as isize); } p
        }
        unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
            unsafe { System.dealloc(p,layout) }; account(-(layout.size() as isize));
        }
        unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
            // System realloc 可在内部先保留新缓冲，再释放旧缓冲；保守地计入两者重叠。
            account(size as isize);
            let next=unsafe { System.realloc(p,layout,size) };
            account(-((if next.is_null() { size } else { layout.size() }) as isize)); next
        }
    }
    #[global_allocator]
    static ALLOC: Probe=Probe;

    #[test]
    fn measure_grid_allocation_probe() {
        use crate::{resources::{Budget, Scope}, term::Terminal, vt::Parser};
        for (name, cols, rows, next_cols, next_rows, input) in [
            ("hard_64m",80,24,79,24,format!("{}\r\n","x".repeat(79)).repeat(50000)),
            ("hard_64m_widen",80,24,81,24,format!("{}\r\n","x".repeat(79)).repeat(50000)),
            ("soft_long",80,24,33,40,"中文xyz".repeat(600000)),
            ("widen_history",8,4,4096,4,"x\r\n".repeat(6000)),
            ("intermediate_tall",1,2048,4096,1,"\x1b[2048;1HX".into()),
            ("narrow_wide",4096,4,1,2048,"中文".repeat(4000)),
            ("height_only",120,40,120,10,"hard\r\n".repeat(1000)),
            ("height_history_index_growth",80,24,80,1,"x\r\n".repeat(32791)),
            ("alternate",80,24,4096,1,"\x1b[?1049hALT".into()),
        ] {
            let pool=Budget::new(usize::MAX,0);
            let _scope=Scope::enter(pool.clone());
            ENABLED.with(|v|v.set(true));
            let mut term=Terminal::new(cols,rows);
            term.set_scrollback_limit(1_000_000);
            Parser::new().advance(&mut term,input.as_bytes());
            let history=term.history().used_bytes();
            let live=LIVE.with(Cell::get);
            PEAK.with(|v|v.set(live));
            let used=pool.snapshot().used;
            let plan=term.prepare_ui_resize(next_cols,next_rows).unwrap();
            let extra=pool.snapshot().used-used;
            let scratch=pool.snapshot().kinds[6];
            if plan.is_stepped() {
                let mut job=crate::term::ResizeJob::new(&term,plan);
                loop { if job.step(&mut term,4096).1 { break; } }
                drop(job);
            } else { term.commit_resize(plan); }
            let delta=PEAK.with(Cell::get).saturating_sub(live).max(0) as usize;
            let grid=term.resource_bytes().0;
            let grid_reserved=pool.snapshot().kinds[5];
            ENABLED.with(|v|v.set(false));
            assert!(delta<=extra,"{name}: {delta}>{extra}");
            assert!(grid<=grid_reserved);
            assert_eq!(pool.snapshot().kinds[6],0);
            drop(term);
            assert_eq!(pool.snapshot().used,0);
            LIVE.with(|v|v.set(0)); PEAK.with(|v|v.set(0));
            eprintln!("GRID_PROBE {{\"name\":\"{name}\",\"history_bytes\":{history},\"additional_peak_requested_bytes\":{delta},\"admitted_extra_bytes\":{extra},\"scratch_reservation_bytes\":{scratch},\"final_grid_capacity_bytes\":{grid},\"final_grid_reservation_bytes\":{grid_reserved}}}");
        }
    }
}
